// Color schemes. Each has a dark and a light palette in newtab.css under
// [data-scheme="…"], generated by tools/make-schemes.mjs. The Light/Dark/System
// theme (src/theme.js) picks which of the two palettes shows; this module only
// names and validates the schemes.
export const SCHEMES = ["teal", "midnight", "ember", "forest", "dusk", "graphite"];

export const SCHEME_LABELS = {
  teal: "Teal", midnight: "Midnight", ember: "Ember",
  forest: "Forest", dusk: "Dusk", graphite: "Graphite",
};

export function normalizeScheme(value) {
  return SCHEMES.includes(value) ? value : "teal";
}
